return {["scripts/actions/weaponskills/drakesbane.lua"]={["Path"]="scripts/actions/weaponskills/drakesbane.lua",["SHA256"]="f57ae420d43a1a904a71068c90a549cedc8b14b0353b043b147a3255d725bf29",["Text"]="-----------------------------------\n-- Drakesbane\n-- Polearm weapon skill\n-- Skill level: N/A\n-- Delivers a fourfold attack. Chance of params.critical hit varies with TP. Ryunohige: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Dragoon) quest.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 4\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.5\n    params.critVaries = { 0.1, 0.3, 0.5 }\n    params.atkVaries  = { 0.8125, 0.8125, 0.8125 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.critVaries = { 0.1, 0.25, 0.4 }\n    end\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/dulling_arrow.lua"]={["Path"]="scripts/actions/weaponskills/dulling_arrow.lua",["SHA256"]="24d3add34243fb5364eb2dcba05b83f51d4c656c5f8d8a224b2d65cca34356b4",["Text"]="-----------------------------------\n-- Dulling Arrow\n-- Archery weapon skill\n-- Skill level: 80\n-- Lowers enemy's INT. Chance of params.critical varies with TP.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:16%  AGI:25%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.16 params.agi_wsc = 0.25\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.2 params.agi_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/earth_crusher.lua"]={["Path"]="scripts/actions/weaponskills/earth_crusher.lua",["SHA256"]="368e77c9785a946bef79bb93d0a140246a87f727fdad4969692169fff0bdcfc7",["Text"]="-----------------------------------\n-- Earth Crusher\n-- Staff weapon skill\n-- Skill Level: 70\n-- Delivers an area of effect earth elemental attack. Damage varies with TP.\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Element: Earth\n-- Modifiers: STR:30%  INT:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.31      3.63\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.3125, 3.625 }\n    params.str_wsc = 0.3 params.int_wsc = 0.3\n    params.ele = xi.element.EARTH\n    params.skill = xi.skill.STAFF\n    params.includemab = true\n    params.dStat = xi.mod.INT\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/empyreal_arrow.lua"]={["Path"]="scripts/actions/weaponskills/empyreal_arrow.lua",["SHA256"]="0e43dcc1ed935ac7e99eb1de1b9650b27c3682d0ca96af0b0b9467ba23680125",["Text"]="-----------------------------------\n-- Empyreal Arrow\n-- Archery weapon skill\n-- Skill level: 250\n-- In order to obtain Empyreal Arrow, the quest From Saplings Grow must be completed.\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:16%  AGI:25%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.75      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 2.0, 2.75, 3.0 }\n    params.atkVaries           = { 2.0, 2.0, 2.0 } -- https://w.atwiki.jp/studiogobli/pages/93.html\n    params.str_wsc             = 0.16\n    params.agi_wsc             = 0.25\n    params.rangedAccuracyBonus = 100 -- https://www.ffxiah.com/forum/topic/52018/luck-of-the-draw-a-corsairs-guide-new/127/#3726841 (Empyreal Arrow is a bow copy of Detonator)\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 1.5, 2.5, 5.0 }\n        params.str_wsc = 0.20\n        params.agi_wsc = 0.50\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/energy_drain.lua"]={["Path"]="scripts/actions/weaponskills/energy_drain.lua",["SHA256"]="6a97c58da323e34ecc7817cb6d7e5dd76573833420c051bfedfcefdb1ddd6ef7",["Text"]="-----------------------------------\n-- Energy Drain\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\n-- https://www.bg-wiki.com/ffxi/Energy_Drain\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local fTPAnchors = { 1.25, 2.5, 4.125 }\n\n    local startingAnchor = math.floor(tp / 1000)\n\n    local multiplier = 0\n\n    if tp >= 3000 then\n        multiplier = fTPAnchors[3]\n    else\n        local basefTP   = fTPAnchors[startingAnchor]\n        local nextfTP   = fTPAnchors[startingAnchor + 1]\n        local multPerTP = (nextfTP - basefTP) / 1000 * (tp - 1000 * startingAnchor)\n        -- TP = 1250; multiplier = 1.25 + ( (2.5 - 1.25) / 1000 * (1250 - (1000 * 1))\n        --            multiplier = 1.25 + (1.25 / 1000) * 250)\n        --            multiplier = 1.25 + 0.3125 = 1.5625\n        multiplier = basefTP + multPerTP\n    end\n\n    local skill = player:getSkillLevel(xi.skill.DAGGER)\n    local wsc   = player:getStat(xi.mod.MND) * 1.0\n\n    local mpRestored = math.floor((math.floor(skill * 0.11) + wsc) * multiplier)\n\n    if target:isUndead() then\n        mpRestored = 0\n    else\n        -- Absorb MP from target\n        mpRestored = target:delMP(mpRestored)\n\n        -- Add stolen MP to player\n        mpRestored = player:addMP(mpRestored)\n    end\n\n    -- Display MP actually given to player\n    action:messageID(target:getID(), xi.msg.basic.SKILL_DRAIN_MP)\n    action:param(target:getID(), mpRestored)\n\n    return 1, 0, false, mpRestored\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/energy_steal.lua"]={["Path"]="scripts/actions/weaponskills/energy_steal.lua",["SHA256"]="cae531a51882f7a92c1135652a68376e69f9e1d4de0e5ee236ecdeee9ba09117",["Text"]="-----------------------------------\n-- Energy Steal\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\n-- https://www.bg-wiki.com/ffxi/Energy_Steal\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local fTPAnchors = { 1.0, 2.1, 3.4 }\n\n    local startingAnchor = math.floor(tp / 1000)\n\n    local multiplier = 0\n\n    if tp >= 3000 then\n        multiplier = fTPAnchors[3]\n    else\n        local basefTP   = fTPAnchors[startingAnchor]\n        local nextfTP   = fTPAnchors[startingAnchor + 1]\n        local multPerTP = (nextfTP - basefTP) / 1000 * (tp - 1000 * startingAnchor)\n        -- TP = 1250; multiplier = 1.0 + ( (2.1 - 1.0) / 1000 * (1250 - (1000 * 1))\n        --            multiplier = 1.0 + (1.0 / 1000) * 250)\n        --            multiplier = 1.0 + 0.275 = 1.275\n        multiplier = basefTP + multPerTP\n    end\n\n    local skill = player:getSkillLevel(xi.skill.DAGGER)\n    local wsc   = player:getStat(xi.mod.MND) * 1.0\n\n    local mpRestored = math.floor((math.floor(skill * 0.11) + wsc) * multiplier)\n\n    if target:isUndead() then\n        mpRestored = 0\n    else\n        -- Absorb MP from target\n        mpRestored = target:delMP(mpRestored)\n\n        -- Add stolen MP to player\n        mpRestored = player:addMP(mpRestored)\n    end\n\n    -- Display MP actually given to player\n    action:messageID(target:getID(), xi.msg.basic.SKILL_DRAIN_MP)\n    action:param(target:getID(), mpRestored)\n\n    return 1, 0, false, mpRestored\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/entropy.lua"]={["Path"]="scripts/actions/weaponskills/entropy.lua",["SHA256"]="2075e63fe23d5be78e3f5643bfc0ae8e93a660755418962532714c70d356f69a",["Text"]="-----------------------------------\n-- Entropy\n-- Scythe weapon skill\n-- Skill level: 357\n-- Description: Delivers a fourfold attack that converts damage dealt into own MP. Damage varies with TP.\n-- In order to obtain Entropy, the quest Martial Mastery must be completed.\n-- MP recovery is about 15~25% of damage dealt.\n-- Aligned with the Shadow Gorget, Soil Gorget & Aqua Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: INT:73~85%, depending on merit points upgrades.\n-- 100%TP    200%TP    300%TP\n-- 0.75       1.25       2.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 4\n    params.ftpMod = { 0.75, 1.25, 2.0 }\n    params.int_wsc = player:getMerit(xi.merit.ENTROPY) * 0.17\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.int_wsc = 0.7 + (player:getMerit(xi.merit.ENTROPY) * 0.03)\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    player:addMP(damage * 0.2)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/evisceration.lua"]={["Path"]="scripts/actions/weaponskills/evisceration.lua",["SHA256"]="f986d42263bfd5f76be85b0e1a70369534fe229c522f873be844713297880311",["Text"]="-----------------------------------\n-- Evisceration\n-- Dagger weapon skill\n-- Skill level: 230\n-- In order to obtain Evisceration, the quest Cloak and Dagger must be completed.\n-- Delivers a fivefold attack. Chance of params.critical hit varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget, Soil Gorget & Light Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Light Belt.\n-- Element: None\n-- Modifiers: DEX:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.numHits    = 5\n    params.ftpMod     = { 1.0, 1.0, 1.0 }\n    params.dex_wsc    = 0.3\n    params.critVaries = { 0.1, 0.25, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true\n        params.ftpMod      = { 1.25, 1.25, 1.25 }\n        params.dex_wsc     = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/exenterator.lua"]={["Path"]="scripts/actions/weaponskills/exenterator.lua",["SHA256"]="008e67e9057451c04487202fa0eace932ae8853b7712256cd9c636da4acd0d32",["Text"]="-----------------------------------\n-- Exenterator\n-- Skill level: 357\n-- Terpsichore: Aftermath effect varies with TP.\n-- In order to obtain Exenterator, the quest Martial Mastery must be completed.\n-- Description: Delivers a fourfold attack that lowers enemy's params.accuracy. Effect duration varies with TP.\n-- Aligned with the Breeze Gorget, Thunder Gorget & Soil Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt & Soil Belt.\n-- Notes: Stacks with itself allowing continuous params.acc down\n-- params.acc down isn't the same as the spell Blind or sources which are the same as blind allowing both to stack\n-- Element: None\n-- Modifiers: AGI:73~85%, depending on merit points upgrades.\n-- 100%TP    200%TP    300%TP\n-- 1.0        1.0       1.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 4\n    params.ftpMod  = { 1, 1, 1 }\n    params.agi_wsc = player:getMerit(xi.merit.EXENTERATOR) * 0.17\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true\n        params.agi_wsc     = 0.7 + player:getMerit(xi.merit.EXENTERATOR) * 0.03\n        params.ftpMod      = { 1.1875, 1.1875, 1.1875 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ACCURACY_DOWN\n    local actionElement = xi.element.EARTH\n    local power         = 20\n    local duration      = math.floor((45 + 45 * tp / 1000) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/expiacion.lua"]={["Path"]="scripts/actions/weaponskills/expiacion.lua",["SHA256"]="38011bd9c953988ad40bfb18e043379214a4638c25c1b0a7d477dc802c8e05f3",["Text"]="-----------------------------------\n-- Expiacion\n-- Sword weapon skill\n-- Skill Level: N/A\n-- Delivers a Twofold attack. Damage varies with TP. Tizona: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Blue Mage) quest.\n-- Aligned with the Aqua Gorget, Snow Gorget & Soil Gorget.\n-- Aligned with the Aqua Belt, Snow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:30% INT:30%\n-- 100%TP    200%TP    300%TP\n-- 1.50      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.5, 2.0, 2.5 }\n    params.str_wsc = 0.3 params.int_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.75, 10.25, 12.5 }\n        params.dex_wsc = 0.2\n    end\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/fast_blade.lua"]={["Path"]="scripts/actions/weaponskills/fast_blade.lua",["SHA256"]="44b3f47459fc90173c3cfdc3a90ad4328cb83db9cd1d9f760d42ebace4b0b674",["Text"]="-----------------------------------\n-- Fast Blade\n-- Sword weapon skill\n-- Skill Level: 5\n-- Delivers a two-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: None\n-- Modifiers: STR:20%  DEX:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.2 params.dex_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.dex_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/fell_cleave.lua"]={["Path"]="scripts/actions/weaponskills/fell_cleave.lua",["SHA256"]="adf858ccb1051b265e5ffc390d975f0fccec5bfb99f8232b3529d04e383fd1d5",["Text"]="-----------------------------------\n-- Fell Cleave\n-- Great Axe weapon skill\n-- Skill Level: 300\n-- Delivers an area attack. Radius varies with TP.\n-- Aligned with the Breeze Gorget, Thunder Gorget & Soil Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR: 60%\n-- 100%TP    200%TP    300%TP\n-- 2.00        2.00      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\n-- TODO: Radius 5y at 2334 TP\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.0, 2.0, 2.0 }\n    params.str_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 2.75, 2.75, 2.75 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/final_heaven.lua"]={["Path"]="scripts/actions/weaponskills/final_heaven.lua",["SHA256"]="bc40726e2ebce1c6d9a46d70e6cd6c1f365aa52db00c291e10d6ab3b2a9a3244",["Text"]="-----------------------------------\n-- Skill: Final Heaven\n-- H2H weapon skill\n-- Skill Level N/A\n-- Additional effect: temporarily enhances Subtle Blow xi.effect.\n-- Mods : VIT:60%\n-- 100%TP     200%TP     300%TP\n-- 3.0x        3.0x    3.0x\n-- +10 Subtle Blow for a short duration after using the weapon skill. (Not implemented)\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    -- number of normal hits for ws\n    params.numHits = 2\n    -- stat-modifiers (0.0 = 0%, 0.2 = 20%, 0.5 = 50%..etc)\n    params.vit_wsc = 0.6\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.vit_wsc = 0.8\n        -- as of 02.03.2022 the ws doesnt yet apply ftp to all stage, was delaied to be done in line with other relic ws\n        -- http://wiki.ffo.jp/html/2426.html and https://forum.square-enix.com/ffxi/threads/55998-October-2019-FINAL-FANTASY-XI-Digest?highlight=2019+update\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/final_paradise.lua"]={["Path"]="scripts/actions/weaponskills/final_paradise.lua",["SHA256"]="cd5a865ada894e71d1b0c37f254e4553d66acc511c9aa062f04690a1df4ad9f6",["Text"]="-----------------------------------\n-- Final Paradise\n-- Hand-to-Hand weapon skill\n-- Is the joke variant of Final Heaven, using the same animation.\n-- Skill level: N/A Only usable when equipping Premium Mogti\n-- Delivers a twofold attack. Paradise varies with TP.\n-- Element: Light\n-- Modifiers: ? (Using Final Heaven as it is based on that WS)\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.vit_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.vit_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    if tpHits + extraHits > 0 then\n        action:messageID(target:getID(), xi.msg.basic.MOTE_OF_PARADISE)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/flaming_arrow.lua"]={["Path"]="scripts/actions/weaponskills/flaming_arrow.lua",["SHA256"]="68ca738b7e0ffa0fd991ffec5b4874ae0e61713fded1823b8346d7b729b24c86",["Text"]="-----------------------------------\n-- Flaming Arrow\n-- Archery weapon skill\n-- Skill level: 5\n-- Deals fire elemental damage. Damage varies with TP.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: Fire\n-- Modifiers: STR:16%  AGI:25%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.16 params.agi_wsc = 0.25\n    params.hybridWS = true\n    params.ele = xi.element.FIRE\n    params.skill = xi.skill.ARCHERY\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.5, 0.75, 1.0 }\n        params.str_wsc = 0.2 params.agi_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/flash_nova.lua"]={["Path"]="scripts/actions/weaponskills/flash_nova.lua",["SHA256"]="560c051947213b8150a8638a4485d204151d64478a4e4d1a394ac0605296317b",["Text"]="-----------------------------------\n-- Flash Nova\n-- Skill level: 290\n-- Delivers light elemental damage. Additional effect: Flash. Chance of effect varies with TP.\n-- Generates a significant amount of Enmity.\n-- Does not stack with Sneak Attack\n-- Aligned with Aqua Gorget.\n-- Aligned with Aqua Belt.\n-- Properties:\n-- Element: Light\n-- Skillchain Properties:Induration Reverberation\n-- Modifiers: STR:30% MND:30%\n-- Damage Multipliers by TP:\n--     100%TP    200%TP     300%TP\n--      3.00     3.00     3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.str_wsc = 0.3 params.mnd_wsc = 0.3\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.CLUB\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.5 params.mnd_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/flat_blade.lua"]={["Path"]="scripts/actions/weaponskills/flat_blade.lua",["SHA256"]="1f02bde0422e1b9bc12f9230252caefd4cb8eaceda8c430231a48d0af6ef6a6c",["Text"]="-----------------------------------\n-- Flat Blade\n-- Sword weapon skill\n-- Skill Level: 75\n-- Stuns enemy. Chance of stunning varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    if math.randomInt(1, 100) <= tp / 30 * applyResistanceAddEffect(player, target, xi.element.THUNDER, 0) then\n        local effectId      = xi.effect.STUN\n        local actionElement = xi.element.THUNDER\n        local power         = 1\n        local duration      = math.floor(4 * applyResistanceAddEffect(player, target, actionElement, 0))\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/freezebite.lua"]={["Path"]="scripts/actions/weaponskills/freezebite.lua",["SHA256"]="986fc497556ae79d7590deea05199d05cf3fae9b6b51cf0e83f76827d083c77c",["Text"]="-----------------------------------\n-- Freezebite\n-- Great Sword weapon skill\n-- Skill Level: 100\n-- Delivers an ice elemental attack. Damage varies with TP.\n-- Aligned with the Snow Gorget & Breeze Gorget.\n-- Aligned with the Snow Belt & Breeze Belt.\n-- Element: Ice\n-- Modifiers: STR:30%  INT:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 1.5, 3.0 }\n    params.str_wsc = 0.3 params.int_wsc = 0.2\n    params.ele = xi.element.ICE\n    params.skill = xi.skill.GREAT_SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/frostbite.lua"]={["Path"]="scripts/actions/weaponskills/frostbite.lua",["SHA256"]="5925cd54aad442e8e5aeced1553a4c0b2c56cf7453524971bffb12e0d8468431",["Text"]="-----------------------------------\n-- Frostbite\n-- Great Sword weapon skill\n-- Skill Level: 70\n-- Delivers an ice elemental attack. Damage varies with TP.\n-- Aligned with the Snow Gorget.\n-- Aligned with the Snow Belt.\n-- Element: Ice\n-- Modifiers: STR:20%  INT:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 2.5 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n    params.ele = xi.element.ICE\n    params.skill = xi.skill.GREAT_SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/full_break.lua"]={["Path"]="scripts/actions/weaponskills/full_break.lua",["SHA256"]="4e1cd3115a8c80114cbc9bdbef73b90986b71d5bd7caffefd50e13567719727e",["Text"]="-----------------------------------\n-- Full Break\n-- Great Axe weapon skill\n-- Skill level: 225 (Warriors only.)\n-- Lowers enemy's attack, defense, params.accuracy, and evasion. Duration of effect varies with TP.\n-- Lowers attack and defense by 12.5%, evasion by 20 points, and estimated to also lower params.accuracy by 20 points.\n-- These enfeebles are given as four seperate status effects, resists calculated seperately for each. They almost always wear off simultaneously, but have been observed to wear off at different times.\n-- Strong against: Coeurls.\n-- Immune: Antica, Cockatrice, Crawlers, Worms.\n-- Will stack with Sneak Attack.\n-- Aligned with the Aqua Gorget & Snow Gorget.\n-- Aligned with the Aqua Belt & Snow Belt.\n-- Element: Earth\n-- Modifiers: STR:50%  VIT:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.5\n    params.vit_wsc = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effects.\n    local effects =\n    {\n        [1] = { xi.effect.ATTACK_DOWN,   xi.element.WATER, 12.5 },\n        [2] = { xi.effect.DEFENSE_DOWN,  xi.element.WIND,  12.5 },\n        [3] = { xi.effect.ACCURACY_DOWN, xi.element.EARTH, 20   },\n        [4] = { xi.effect.EVASION_DOWN,  xi.element.ICE,   20   },\n    }\n\n    for index = 1, #effects do\n        local effectId      = effects[index][1]\n        local actionElement = effects[index][2]\n        local power         = effects[index][3]\n        local duration      = math.floor(60 + 3 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/full_swing.lua"]={["Path"]="scripts/actions/weaponskills/full_swing.lua",["SHA256"]="38cd252ffba72b54cb94028467fbee8b83a2748826c9d72ea61f7d322bac3de3",["Text"]="-----------------------------------\n-- Full Swing\n-- Staff weapon skill\n-- Skill Level: 200\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget & Thunder Gorget.\n-- Aligned with the Flame Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      3.00      5.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 3.0, 5.0 }\n    params.str_wsc = 0.5\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/gale_axe.lua"]={["Path"]="scripts/actions/weaponskills/gale_axe.lua",["SHA256"]="e6ae785ba7ed7bbc9bb8509bf0022e1684be05646589a94bc1266b4c53a4e661",["Text"]="-----------------------------------\n-- Gale Axe\n-- Axe weapon skill\n-- Skill level: 70\n-- Deals wind elemental damage. Chokes target. Chance of choking varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Breeze Gorget.\n-- Aligned with the Breeze Belt.\n-- Element: Wind\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.CHOKE\n    local actionElement = xi.element.WIND\n    local power         = 5\n    local maccParams =\n    {\n        effectId       = xi.effect.CHOKE,\n        magicalElement = xi.element.WIND,\n        skillType      = xi.skill.AXE,\n    }\n\n    local resist   = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n    local duration = math.floor(60 * resist)\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/garland_of_bliss.lua"]={["Path"]="scripts/actions/weaponskills/garland_of_bliss.lua",["SHA256"]="d7c2cfab5dfe920746832e289ea133526dc3210b59755203a6f5a5ee89533295",["Text"]="-----------------------------------\n-- Garland Of Bliss\n-- Staff weapon skill\n-- Skill level: N/A\n-- Lowers target's defense. Duration of effect varies with TP. Nirvana: Aftermath effect varies with TP.\n-- Reduces enemy's defense by 12.5%.\n-- Available only after completing the Unlocking a Myth (Summoner) quest.\n-- Aligned with the Flame Gorget, Light Gorget & Aqua Gorget.\n-- Aligned with the Flame Belt, Light Belt & Aqua Belt.\n-- Element: Light\n-- Modifiers: MND:40%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.00      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 2, 2, 2 }\n    params.mnd_wsc    = 0.4\n    params.ele        = xi.element.LIGHT\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    -- params.dStat = xi.mod.MND -- (pMND-mMND)×2 (Not supported in weaponskills.lua currently)\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 2.25, 2.25, 2.25 }\n        params.str_wsc = 0.3\n        params.mnd_wsc = 0.7\n    end\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 12.5\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/gate_of_tartarus.lua"]={["Path"]="scripts/actions/weaponskills/gate_of_tartarus.lua",["SHA256"]="53725954b1b745737c2b2613871ba658f59db86ed3082d84445e5a6e39c49137",["Text"]="-----------------------------------\n-- Gate Of Tartarus\n-- Staff weapon skill\n-- Skill Level: N/A\n-- Lowers target's attack. Additional effect: Refresh\n-- Refresh effect is 8mp/tick for 20 sec per 100 TP.\n-- Available only when equipped with the Relic Weapons Thyrus (Dynamis use only) and Claustrum, or the Chthonic Staff once the Latent Effect has been activated.\n-- These Relic Weapons are only available to Black Mages and Summoners. As such, only these jobs may use this Weapon Skill.\n-- Aligned with the Aqua Gorget & Snow Gorget.\n-- Aligned with the Aqua Belt & Snow Belt.\n-- Element: None\n-- Modifiers: CHR:60%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3, 3, 3 }\n    params.chr_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.chr_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ATTACK_DOWN\n    local actionElement = xi.element.WATER\n    local power         = 18.75 -- TODO : JP Wiki claims this power scales with ilvl. Denotes 18.75% at base. https://wiki.ffo.jp/html/3093.html\n    local duration      = math.floor(120 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/geirskogul.lua"]={["Path"]="scripts/actions/weaponskills/geirskogul.lua",["SHA256"]="d3e511d17c42fef36f6ad2302346ba9363fc7d874c8ca77d9f8c7ffd3cfae8e2",["Text"]="-----------------------------------\n-- Geirskogul\n-- Polearm weapon skill\n-- Skill Level: N/A\n-- Gae Assail/Gungnir: Shock Spikes.\n-- This weapon skill is only available with the stage 5 relic Polearm Gungnir, within Dynamis with the stage 4 Gae Assail, or by activating the latent effect on the Skogul Lance.\n-- Aligned with the Light Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Light Belt, Aqua Belt & Snow Belt.\n-- Element: None\n-- Modifiers: AGI:60%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.agi_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 0.8 params.agi_wsc = 0.0\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/glory_slash.lua"]={["Path"]="scripts/actions/weaponskills/glory_slash.lua",["SHA256"]="70a00737e047b0825b1a536eb0ef54888dad329f7caff1c001549ee44db577d6",["Text"]="-----------------------------------\n-- Glory Slash\n-- Sword weapon skill\n-- Skill Level: NA\n-- Only avaliable during Campaign Battle while weilding Lex Talionis.\n-- Delivers and area attack that deals triple damage. Damage varies with TP. Additional effect Stun.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: Light\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.50      4.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3, 3.5, 4 }\n    params.str_wsc = 0.3\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local duration      = math.floor(tp / 500 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/ground_strike.lua"]={["Path"]="scripts/actions/weaponskills/ground_strike.lua",["SHA256"]="184f2ee6937d0a1309c7552839b322d346f604d8bed3f617d2a7f1116f655cc4",["Text"]="-----------------------------------\n-- Ground Strike\n-- Great Sword weapon skill\n-- Skill level: 250 QUESTED\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Modifiers: STR:50% INT:50%\n-- 100%TP     200%TP     300%TP\n-- 1.5         1.75    3.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.5, 1.75, 3.0 }\n    params.str_wsc = 0.5\n    params.int_wsc = 0.5\n    params.atkVaries = { 1.75, 1.75, 1.75 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/guillotine.lua"]={["Path"]="scripts/actions/weaponskills/guillotine.lua",["SHA256"]="d3a7f65278aee6f2ff519db47cf88be599eeb8253cb2a98539145aca74736f22",["Text"]="-----------------------------------\n-- Guillotine\n-- Scythe weapon skill\n-- Skill level: 200\n-- Delivers a four-hit attack. Duration varies with TP.\n-- Modifiers: STR:25%  MND:25%\n-- 100%TP     200%TP     300%TP\n-- 0.875    0.875    0.875\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 4\n    params.ftpMod  = { 0.875, 0.875, 0.875 }\n    params.str_wsc = 0.25\n    params.mnd_wsc = 0.25\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.3\n        params.mnd_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.SILENCE\n    local actionElement = xi.element.WIND\n    local power         = 1\n    local duration      = math.floor((30 + 3 * tp / 100) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/gust_slash.lua"]={["Path"]="scripts/actions/weaponskills/gust_slash.lua",["SHA256"]="82b19243629372476f496fbc1066a20fe10728947d6f3edf488839f41149dc65",["Text"]="-----------------------------------\n-- Gust Slash\n-- Dagger weapon skill\n-- Skill level: 40\n-- Deals wind elemental damage. Damage varies with TP.\n-- Will not stack with Sneak Attack.\n-- Aligned with the Breeze Gorget.\n-- Aligned with the Breeze Belt.\n-- Element: Wind\n-- Modifiers: DEX:20%  INT:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 2.5 }\n    params.dex_wsc = 0.2 params.int_wsc = 0.2\n    params.ele = xi.element.WIND\n    params.skill = xi.skill.DAGGER\n    params.includemab = true\n    params.dStat = xi.mod.INT\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        -- http://wiki.ffo.jp/html/682.html\n        params.dex_wsc = 0.4 params.int_wsc = 0.4\n        params.ftpMod = { 1.0, 2.0, 3.0 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/hard_slash.lua"]={["Path"]="scripts/actions/weaponskills/hard_slash.lua",["SHA256"]="7695afee367b1cd3ea1ed89fc7267c5bb788c625a879bd88076d2e87f4fabbc2",["Text"]="-----------------------------------\n-- Hard Slash\n-- Great Sword weapon skill\n-- Skill level: 5\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Modifiers: STR:30%\n-- 100%TP     200%TP     300%TP\n-- 1.5         1.75        2.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.5, 1.75, 2.0 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/heavy_shot.lua"]={["Path"]="scripts/actions/weaponskills/heavy_shot.lua",["SHA256"]="5777b3db343df075b6d674b10fec04ee68708679491f8e05007be97c6aae2cf7",["Text"]="-----------------------------------\n-- Heavy Shot\n-- Marksmanship weapon skill\n-- Skill Level: 225\n-- Delivers a single-hit attack. Chance of params.critical varies with TP.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: AGI:30%\n-- 100%TP    200%TP    300%TP\n-- 3.50      3.50      3.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.5, 3.5, 3.5 }\n    params.agi_wsc = 0.3\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.agi_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/heavy_swing.lua"]={["Path"]="scripts/actions/weaponskills/heavy_swing.lua",["SHA256"]="4610d1a24d9ec6725a7b8189ea29c9c406e65aa4175851c4a1c20c36e703b725",["Text"]="-----------------------------------\n-- Heavy Swing\n-- Staff weapon skill\n-- Skill Level: 5\n-- Deacription:Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.25      2.25\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.25, 2.25 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"}};
